import { Component, ReactNode, ErrorInfo, ReactElement } from 'react';

// Discriminated union of all possible error types
type AppError =
  | { type: 'network'; message: string; retryable: boolean }
  | { type: 'auth'; message: string; redirectTo: string }
  | { type: 'not-found'; message: string; resource: string }
  | { type: 'unknown'; message: string; stack?: string };

interface ErrorBoundaryProps {
  children: ReactNode;
  fallback?: (error: AppError, retry: () => void) => ReactElement;
  onError?: (error: AppError, info: ErrorInfo) => void;
}

interface ErrorBoundaryState {
  error: AppError | null;
}

function classifyError(error: Error): AppError {
  if (error.message.includes('fetch') || error.message.includes('network')) {
    return { type: 'network', message: error.message, retryable: true };
  }
  if (error.message.includes('unauthorized') || error.message.includes('401')) {
    return { type: 'auth', message: 'Session expired', redirectTo: '/login' };
  }
  if (error.message.includes('not found') || error.message.includes('404')) {
    return { type: 'not-found', message: error.message, resource: 'page' };
  }
  return { type: 'unknown', message: error.message, stack: error.stack };
}

class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  state: ErrorBoundaryState = { error: null };

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    const classified = classifyError(error);
    return { error: classified };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    if (this.state.error) {
      this.props.onError?.(this.state.error, info);
    }
  }

  retry = () => {
    this.setState({ error: null });
  };

  render() {
    if (this.state.error) {
      if (this.props.fallback) {
        return this.props.fallback(this.state.error, this.retry);
      }
      return <DefaultErrorFallback error={this.state.error} onRetry={this.retry} />;
    }
    return this.props.children;
  }
}

function DefaultErrorFallback({ error, onRetry }: { error: AppError; onRetry: () => void }) {
  return (
    <div className="error-fallback">
      <h2>Something went wrong</h2>
      <p>{error.message}</p>
      {error.type === 'network' && (
        <button onClick={onRetry}>Try Again</button>
      )}
      {error.type === 'auth' && (
        <a href={error.redirectTo}>Go to Login</a>
      )}
    </div>
  );
}

class ApiError extends Error {
  constructor(
    public status: number,
    message: string,
    public retryAfter?: number
  ) {
    super(message);
    this.name = 'ApiError';
  }
}

class ValidationError extends Error {
  constructor(
    public fields: Record<string, string[]>
  ) {
    super('Validation failed');
    this.name = 'ValidationError';
  }
}

class AuthError extends Error {
  constructor(public redirectTo: string = '/login') {
    super('Authentication required');
    this.name = 'AuthError';
  }
}

// In your data fetching code
async function fetchUser(id: string): Promise<User> {
  const response = await fetch(`/api/users/${id}`);
  if (response.status === 401) throw new AuthError('/login');
  if (response.status === 404) throw new ApiError(404, 'User not found');
  if (!response.ok) throw new ApiError(response.status, response.statusText, 60);
  return response.json();
}

// In the error boundary
function classifyError(error: Error): AppError {
  if (error instanceof AuthError) {
    return { type: 'auth', message: error.message, redirectTo: error.redirectTo };
  }
  if (error instanceof ApiError) {
    return {
      type: 'network',
      message: `Server error (${error.status})`,
      retryable: error.status >= 500,
    };
  }
  if (error instanceof ValidationError) {
    return { type: 'unknown', message: error.message };
  }
  return { type: 'unknown', message: error.message };
}

function SmartFallback({ error, onRetry }: { error: AppError; onRetry: () => void }) {
  const styles = {
    network: { icon: '📡', title: 'Connection Problem' },
    auth: { icon: '🔒', title: 'Please Log In' },
    'not-found': { icon: '🔍', title: 'Not Found' },
    unknown: { icon: '⚠️', title: 'Unexpected Error' },
  };

  const config = styles[error.type];

  return (
    <div className="error-container">
      <span className="error-icon">{config.icon}</span>
      <h2>{config.title}</h2>
      <p>{error.message}</p>
      <div className="error-actions">
        {error.type === 'network' && (
          <button onClick={onRetry}>Retry Request</button>
        )}
        {error.type === 'auth' && (
          <a href={error.redirectTo} className="btn-primary">Sign In</a>
        )}
        {error.type === 'not-found' && (
          <a href="/" className="btn-secondary">Go Home</a>
        )}
        <button onClick={() => window.location.reload()}>Reload Page</button>
      </div>
    </div>
  );
}

// Usage wrapping the app
<ErrorBoundary
  fallback={(error, retry) => <SmartFallback error={error} onRetry={retry} />}
  onError={(error) => logToService(error)}
>
  <App />
</ErrorBoundary>
